function closeModal(){const root=$('modalRoot');root.innerHTML='';root.className='hidden';paused=false;clearControls();clock.getDelta();renderer.domElement.focus({preventScroll:true});}
function modal(html,wide=false){const root=$('modalRoot');root.className='modal-shade';root.innerHTML=`<section class="modal ${wide?'wide':''} pop-in" role="dialog" aria-modal="true" aria-labelledby="dialogTitle">${html}</section>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);root.querySelector('button')?.focus();}
function showHow(){if(mode==='driving')paused=true;modal(`<button class="modal-close" data-close aria-label="Close">×</button><h2 id="dialogTitle">DRIVE THE NIGHT.</h2><p>Follow the mint arrows to a pickup. Stop inside the ring to let a passenger in. Then drive to their blue hideout ring and stop to collect the fare.</p><div class="instruction"><span>Pickups</span><b>GREEN easy · GOLD risky · RED hot</b></div><div class="instruction"><span>Keep your streak</span><b>DELIVERIES BOOST YOUR MULTIPLIER</b></div><div class="instruction"><span>Save your earnings</span><b>STOP AT THE GARAGE. BANK YOUR HAUL.</b></div><div class="desktop-only"><div class="instruction"><span>Drive / reverse</span><b>WASD / ARROW KEYS</b></div><div class="instruction"><span>Handbrake drift / nitro</span><b>SPACE / SHIFT</b></div><div class="instruction"><span>Camera / garage route</span><b>C / TAB</b></div><div class="instruction"><span>Bank haul / recover car</span><b>E / R</b></div></div><div class="mobile-only"><p>Hold GAS and steer with LEFT / RIGHT. BRAKE slows you down, then reverses. Hold DRIFT for tight corners and NITRO for a burst of speed.</p></div><p>Hot pickups bring police. Break their line of sight to lose your stars. Deliveries add 40 seconds. Crashing or running out of time loses your unbanked haul.</p><button class="primary" data-close>LET’S DRIVE <span>↗</span></button>`);}
function showGarage(){if(!ready)return;const cards=Object.values(CARS).map((c,i)=>{const owns=profile.unlocked.includes(c.id),selected=profile.selected===c.id;return`<article class="car-card ${selected?'selected':''}"><div class="car-art"><img src="${carThumbnail(c)}" alt="${c.name} in your selected paint"><span class="car-num">0${i+1}</span></div><h3>${c.name}</h3><p>${c.description}</p><div class="car-spec">${Math.round(c.speed*4.6)} KM/H · ${c.seats} SEATS<br>${c.health} INTEGRITY</div><button data-car="${c.id}" ${!owns&&profile.credits<c.price?'disabled':''}>${selected?'EQUIPPED':owns?'EQUIP':c.price.toLocaleString()+' CR'}</button></article>`;}).join('');modal(`<button class="modal-close" data-close aria-label="Close garage">×</button><div class="garage-head"><h2 id="dialogTitle">LAST EXIT GARAGE</h2><div class="garage-balance">BANKED CREDITS<strong>${profile.credits.toLocaleString()}</strong></div></div><div class="cars">${cards}</div><div class="paints"><span>PAINT</span>${PAINTS.map((p,i)=>`<button class="swatch ${profile.paint===i?'active':''}" style="background:${p}" data-paint="${i}" aria-label="${['Sunburst','Turquoise','Vermilion','Electric blue'][i]} paint" aria-pressed="${profile.paint===i}"></button>`).join('')}</div><p class="note">${storageAvailable?'Your cars, credits, and paint are saved on this device.':'Storage is unavailable. Progress will last only for this session.'} Credits are earned in this game.</p><button class="primary" id="garageDrive">HIT THE STREETS <span>↗</span></button>`,true);
 document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>{const id=b.dataset.car;if(profile.unlocked.includes(id))profile.selected=id;else if(!buyCar(profile,id))return;saveProfile();replacePlayer();refreshMenu();sound(560,.16,'triangle',.05,180);showGarage();});document.querySelectorAll('[data-paint]').forEach(b=>b.onclick=()=>{profile.paint=Number(b.dataset.paint);saveProfile();replacePlayer();refreshMenu();showGarage();});$('garageDrive').onclick=startRun;
}
function showPause(){if(mode!=='driving')return;paused=true;clearControls();modal(`<h2 id="dialogTitle">ENGINE IDLING.</h2><p>The city can wait. Your shift is paused.</p><button id="resumeBtn" class="primary">RESUME SHIFT <span>↗</span></button><div class="modal-secondary"><button id="recoverBtn" class="small-btn">RECOVER CAR</button><button id="cameraBtn" class="small-btn">CAMERA: ${profile.camera.toUpperCase()}</button><button id="pauseSound" class="small-btn">SOUND ${profile.muted?'OFF':'ON'}</button></div><div class="modal-secondary"><button id="restartBtn" class="small-btn">RESTART SHIFT</button><button id="quitBtn" class="small-btn">BACK TO MENU</button></div><p class="note">Recover moves you to the nearest road. Your wanted level stays.</p>`);$('resumeBtn').onclick=closeModal;$('recoverBtn').onclick=()=>{closeModal();recover();};$('cameraBtn').onclick=()=>{cycleCamera();$('cameraBtn').textContent='CAMERA: '+profile.camera.toUpperCase();};$('pauseSound').onclick=()=>{toggleSound();$('pauseSound').textContent='SOUND '+(profile.muted?'OFF':'ON');};$('restartBtn').onclick=startRun;$('quitBtn').onclick=returnMenu;}
function showJobs(){if(mode!=='driving')return;paused=true;clearControls();const available=pickups.filter(p=>!p.job.picked&&p.job.cooldown<=0).sort((a,b)=>dist(player,a.stop)-dist(player,b.stop));const full=run.passengers.length>=player.config.seats;modal(`<button class="modal-close" data-close aria-label="Close jobs">×</button><h2 id="dialogTitle">CHOOSE YOUR FARE.</h2><p>${full?'All seats are full. Drop off a passenger before picking up another.':'Easy fares keep things quiet. Hot pickups pay more and bring the police.'}</p><div class="job-list">${available.map(p=>`<button class="job-option" data-job="${p.stop.id}" ${full?'disabled':''}><span><strong>${p.stop.name}</strong><small>${p.job.name} · ${Math.round(dist(player,p.stop))} m<br>TO ${p.job.dest.name}</small></span><b>${Math.round(p.job.value*run.combo).toLocaleString()} CR</b></button>`).join('')||'<p>No pickups are available yet. Finish a delivery or head to the garage.</p>'}</div>`);document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{pickupLock=b.dataset.job;targetLock=null;bankRoute=false;closeModal();refreshRoute();updateHUD();});}
function showCredits(){modal(`<button class="modal-close" data-close aria-label="Close credits">×</button><h2 id="dialogTitle">GOOD COMPANY.</h2><p>Animated characters and street props by <a href="https://kenney.nl" target="_blank" rel="noopener noreferrer">Kenney</a>, used under CC0.</p><p>Blocky Characters · City Kit Commercial · City Kit Roads. City design, driving, missions, and sound effects made for GETAWAY.</p><p>Vehicles by <a href="https://rgsdev.itch.io/free-low-poly-vehicles-pack" target="_blank" rel="noopener noreferrer">RGS_Dev</a> (CC0). <a href="/assets/packs/rgsdev-vehicles.zip" download>Download the original 21-vehicle pack</a>.</p><p>Three.js (MIT). Space Mono and Silkscreen (SIL Open Font License).</p><button class="primary" data-close>BACK TO THE NIGHT <span>↗</span></button>`);}
function toggleSound(){initAudio();profile.muted=!profile.muted;saveProfile();refreshMenu();updateAudio();}
function cycleCamera(){profile.camera=profile.camera==='chase'?'high':'chase';saveProfile();}
function replacePlayer(){if(playerView){world.remove(playerView.group);disposeVehicle(playerView);}const cfg=CARS[profile.selected];player=createCar(cfg,HOME.x,HOME.z,-Math.PI/2);playerView=carView(cfg.model,cfg.scale,PAINTS[profile.paint]);animateCar(playerView,player,0);}
function cleanupRun(){for(const c of cops){world.remove(c.view.group);disposeVehicle(c.view);}cops.length=0;for(let i=destructibles.length-1;i>=0;i--){const d=destructibles[i];if(d.roadblock){world.remove(d.view);destructibles.splice(i,1);}else{d.broken=false;d.view.visible=true;d.view.position.set(d.x,.12,d.z);d.view.rotation.set(0,d.rotation,0);}}
 for(const d of debris)world.remove(d.mesh);debris.length=0;for(const s of sparks){world.remove(s.mesh);s.mesh.geometry.dispose();}sparks.length=0;for(const t of trails){world.remove(t.mesh);t.mesh.geometry.dispose();t.mesh.material.dispose();}trails.length=0;
}
function resetRun(){cleanupRun();replacePlayer();run=createRun();for(const p of pickups){p.index++;p.job=makeJob(p.stop,p.index);p.actor.group.visible=true;p.marker.root.visible=true;}for(const d of drops)d.marker.root.visible=false;targetLock=null;pickupLock=null;bankRoute=false;target=null;routeTimer=0;routePoints=[];pickupProgress=0;pickupKey='';damageCooldown=0;copSpawnTimer=0;roadblockTimer=0;nearMissTimer=0;bankReady=false;lastRecovery=-30;clearControls();cameraHeading=player.heading;cameraTarget.set(player.x,0,player.z);$('bankBtn').classList.add('hidden');$('stopProgress').classList.add('hidden');$('damageFlash').style.opacity=0;}
function startRun(){if(!ready)return;closeModal();initAudio();resetRun();mode='driving';['menu','topbar','bottomBar','carPlaque'].forEach(id=>$(id).classList.add('hidden'));$('hud').classList.remove('hidden');chooseTarget();refreshRoute();updateHUD();toast(touch?'Hold GAS. Follow the arrows to your first fare.':'W to accelerate. Follow the arrows to your first fare.','good',4);sound(250,.2,'triangle',.05,330);}
function returnMenu(){closeModal();mode='menu';if(ready)resetRun();['menu','topbar','bottomBar','carPlaque'].forEach(id=>$(id).classList.remove('hidden'));$('hud').classList.add('hidden');arrows.count=0;refreshMenu();}
function finish(success,reason=''){if(mode!=='driving'||!settleRun(run,profile,success))return;mode=success?'banked':'busted';saveProfile();clearControls();jingle(success);$('bankBtn').classList.add('hidden');$('stopProgress').classList.add('hidden');const lost=Math.floor(run.haul+run.style);modal(`<div class="result-kicker">${success?'BACK IN ONE PIECE':'THE NIGHT CAUGHT UP'}</div><h2 id="dialogTitle">${success?'MONEY IN THE GARAGE.':reason||'BUSTED.'}</h2><div class="result-score">${run.total.toLocaleString()}</div><div class="score-label">CREDITS BANKED${success?'':' · '+lost.toLocaleString()+' LOST'}</div><div class="result-stats"><div><small>PASSENGERS SAVED</small><strong>${run.deliveries}</strong></div><div><small>STREAK MULTIPLIER</small><strong>×${run.combo.toFixed(2)}</strong></div><div><small>STYLE BONUS</small><strong>${Math.floor(run.style)}</strong></div></div><p>${success?'That haul is safe. Upgrade your ride or go back for another shift.':'Break line of sight to lose the police. Bank early if your car or your clock is running low.'}</p><button id="againBtn" class="primary">ONE MORE SHIFT <span>↗</span></button><div class="modal-secondary"><button id="resultGarage" class="small-btn">GARAGE · ${profile.credits.toLocaleString()} CR</button><button id="resultMenu" class="small-btn">BACK TO MENU</button></div><p class="note">Arcade credits only. Progress is saved on this device.</p>`);$('againBtn').onclick=startRun;$('resultGarage').onclick=()=>{returnMenu();showGarage();};$('resultMenu').onclick=returnMenu;refreshMenu();}

$('playBtn').onclick=startRun;$('garageBtn').onclick=showGarage;$('howBtn').onclick=showHow;$('helpBtn').onclick=showHow;$('creditsBtn').onclick=showCredits;$('soundBtn').onclick=toggleSound;$('pauseBtn').onclick=showPause;$('jobsBtn').onclick=showJobs;$('routeBtn').onclick=toggleGarageRoute;$('bankBtn').onclick=bank;
function toggleGarageRoute(){bankRoute=!bankRoute;targetLock=null;pickupLock=null;chooseTarget();refreshRoute();updateHUD();}
function bank(){if(mode!=='driving'||paused||!bankReady)return;finish(true);}
function recover(){if(mode!=='driving'||time-lastRecovery<4)return;const road=closestRoad(player);player.x=road.x;player.z=road.z;player.y=0;player.vy=0;player.vx=0;player.vz=0;player.health=Math.max(1,player.health-8);lastRecovery=time;toast('Back on the road. −8 integrity.','bad');}
addEventListener('keydown',e=>{
 if(e.code==='Tab'&&!$('modalRoot').classList.contains('hidden')){const focus=[...$('modalRoot').querySelectorAll('button:not([disabled]),a[href]')];if(!focus.length)return;const i=focus.indexOf(document.activeElement);e.preventDefault();focus[(i+(e.shiftKey?-1:1)+focus.length)%focus.length].focus();return;}
 if(e.code==='Escape'){if($('modalRoot').classList.contains('hidden'))showPause();else if(mode==='driving'||mode==='menu')closeModal();return;}
 if(mode!=='driving'||paused)return;if(['Space','Tab','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!keys[e.code]){if(e.code==='KeyC')cycleCamera();if(e.code==='KeyJ')showJobs();if(e.code==='Tab')toggleGarageRoute();if(e.code==='KeyE')bank();if(e.code==='KeyR')recover();}keys[e.code]=true;
});addEventListener('keyup',e=>{keys[e.code]=false;});
for(const [id,key]of [['leftBtn','left'],['rightBtn','right'],['brakeBtn','reverse'],['gasBtn','gas'],['driftBtn','drift'],['nitroBtn','boost']]){const b=$(id);b.addEventListener('pointerdown',e=>{if(mode!=='driving'||paused)return;e.preventDefault();b.setPointerCapture(e.pointerId);mobile[key]=true;b.classList.add('active');});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>{mobile[key]=false;b.classList.remove('active');});}
addEventListener('blur',()=>{clearControls();if(mode==='driving'&&!paused)showPause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='driving'&&!paused)showPause();});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());

function chooseTarget(){
 if(bankRoute){target={kind:'garage',point:HOME,name:HOME.name};return;}
 if(targetLock){const fare=run.passengers.find(p=>p.id===targetLock);if(fare){target={kind:'drop',point:fare.dest,name:fare.dest.name,fare};return;}targetLock=null;}
 if(pickupLock&&run.passengers.length<player.config.seats){const p=pickups.find(p=>p.stop.id===pickupLock&&!p.job.picked&&p.job.cooldown<=0);if(p){target={kind:'pickup',point:p.stop,name:p.stop.name,pickup:p};return;}pickupLock=null;}
 if(run.passengers.length){const fare=[...run.passengers].sort((a,b)=>dist(player,a.dest)-dist(player,b.dest))[0];target={kind:'drop',point:fare.dest,name:fare.dest.name,fare};return;}
 const available=pickups.filter(p=>!p.job.picked&&p.job.cooldown<=0);if(available.length){const p=available.sort((a,b)=>dist(player,a.stop)-dist(player,b.stop))[0];target={kind:'pickup',point:p.stop,name:p.stop.name,pickup:p};}else target={kind:'garage',point:HOME,name:HOME.name};
}
function refreshRoute(){chooseTarget();routePoints=target?route(player,target.point):[];let count=0;for(let i=0;i<routePoints.length-1;i++){const a=routePoints[i],b=routePoints[i+1],length=dist(a,b);if(length<.1)continue;for(let d=2;d<length&&count<70;d+=4.8){const f=d/length;tempObject.position.set(a.x+(b.x-a.x)*f,.14,a.z+(b.z-a.z)*f);tempObject.rotation.set(0,Math.atan2(b.x-a.x,b.z-a.z),0);tempObject.updateMatrix();arrows.setMatrixAt(count++,tempObject.matrix);}}arrows.count=count;arrows.instanceMatrix.needsUpdate=true;arrows.computeBoundingSphere();}
function stopActivities(dt){
 for(const p of pickups){if(p.job.cooldown>0){p.job.cooldown-=dt;if(p.job.cooldown<=0){p.job=makeJob(p.stop,++p.index);p.actor.group.visible=true;}}p.marker.root.visible=!p.job.picked&&p.job.cooldown<=0;p.actor.group.visible=p.marker.root.visible;}
 for(const d of drops)d.marker.root.visible=run.passengers.some(p=>p.dest.id===d.stop.id);
 bankReady=dist(player,HOME)<5&&player.speed<2.7&&(run.haul+run.style)>0&&player.y<.4;
 $('bankBtn').classList.toggle('hidden',!bankReady);if(bankReady){$('bankBtn').innerHTML=`BANK ${Math.floor(run.haul+run.style).toLocaleString()} CREDITS <small>${touch?'TAP TO FINISH YOUR SHIFT':'E · FINISH YOUR SHIFT'}</small>`;}
 let activity=null;const drop=run.passengers.find(p=>dist(player,p.dest)<4.1);if(drop)activity={kind:'drop',id:drop.id,point:drop.dest};
 if(!activity&&run.passengers.length<player.config.seats){const p=pickups.find(p=>!p.job.picked&&p.job.cooldown<=0&&dist(player,p.stop)<4.1);if(p)activity={kind:'pickup',id:p.job.id,pickup:p};}
 if(activity){if(pickupKey!==activity.id){pickupKey=activity.id;pickupProgress=0;}$('stopProgress').classList.toggle('hidden',bankReady);$('stopLabel').textContent=player.speed>3?'SLOW DOWN · STOP IN THE RING':activity.kind==='drop'?'PASSENGER GETTING OUT…':'PASSENGER GETTING IN…';
  if(player.speed<3&&player.y<.3)pickupProgress+=dt;else pickupProgress=Math.max(0,pickupProgress-dt*2);$('stopFill').style.width=Math.min(100,pickupProgress/.9*100)+'%';
  if(pickupProgress>=.9){if(activity.kind==='pickup'){const p=activity.pickup;if(pickup(run,p.job,player.config)){p.actor.group.visible=false;bankRoute=false;targetLock=null;pickupLock=null;toast(p.job.name+' · '+p.job.dest.name,p.job.level>1?'bad':'good',3.5);sound(510,.13,'triangle',.06,240);}}
   else{const result=deliver(run,activity.id);if(result){const station=pickups.find(p=>p.stop.id===result.passenger.stopId);if(station)station.job.cooldown=22;toast('DELIVERED +'+result.payment.toLocaleString()+' CR · +40 SECONDS','good');pop('×'+run.combo.toFixed(2)+' DELIVERY STREAK');jingle(true);if(targetLock===activity.id)targetLock=null;}}
   pickupProgress=0;pickupKey='';refreshRoute();updateHUD();
  }
 }else{pickupProgress=0;pickupKey='';$('stopProgress').classList.add('hidden');}
}
function aiSteer(entity,path,desiredSpeed,dt){
 const car=entity.car;while(path.length>1&&dist(car,path[0])<4)path.shift();let point=path[0];if(!point)return;
 const angle=Math.atan2(point.x-car.x,point.z-car.z),difference=Math.atan2(Math.sin(angle-car.heading),Math.cos(angle-car.heading));let goal=desiredSpeed;if(Math.abs(difference)>.5)goal=Math.min(goal,7);if(path.length>1&&dist(car,point)<9){const next=path[1],nextAngle=Math.atan2(next.x-point.x,next.z-point.z);if(Math.abs(Math.atan2(Math.sin(nextAngle-angle),Math.cos(nextAngle-angle)))>.4)goal=Math.min(goal,8);}
 const throttle=car.speed>goal+1?-1:car.speed<goal-1?1:.15;drive(car,{throttle,steer:clamp(-difference*1.6,-1,1),brake:Math.abs(difference)>1.2&&car.speed>6},dt);animateCar(entity.view,car,dt,clamp(-difference,-1,1));
}
function updateTraffic(dt){for(const t of traffic){let p=t.path[t.index];if(dist(t.car,p)<4){t.index=(t.index+1)%t.path.length;p=t.path[t.index];}aiSteer(t,[p,t.path[(t.index+1)%t.path.length]],8,dt);if(mode==='driving')vehicleContact(t,false,dt);}}
function spawnCop(){const choices=[];for(const x of ROAD)for(const z of ROAD){const d=dist({x,z},player);if(d>29&&d<85)choices.push({x,z});}if(!choices.length)return;const at=choices[Math.floor(Math.random()*choices.length)],cfg={...CARS.coupe,speed:17+Math.min(4,run.wanted),accel:16,grip:11,steer:2.8},car=createCar(cfg,at.x,at.z,Math.atan2(player.x-at.x,player.z-at.z));const view=carView('police-car',1.65);const [red,blue]=view.policeLights;cops.push({car,view,path:route(car,player),timer:0,lastSeen:{x:player.x,z:player.z},lost:0,red,blue,contact:0,near:-10});}
function vehicleContact(other,isCop,dt){
 const d=dist(player,other.car),relative=Math.hypot(player.vx-other.car.vx,player.vz-other.car.vz);
 if(d<3&&Math.abs(player.y-other.car.y)<1.4){const nx=(player.x-other.car.x)/(d||1),nz=(player.z-other.car.z)/(d||1),overlap=3-d;const nxp=player.x+nx*overlap*.55,nzp=player.z+nz*overlap*.55;if(!blocked(nxp,nzp,1))player.x=nxp,player.z=nzp;player.vx+=nx*4*dt*20;player.vz+=nz*4*dt*20;other.car.vx-=nx*3;other.car.vz-=nz*3;if(relative>4&&damageCooldown<=0){damage(clamp(relative*.7,4,15));run.crashes++;sound(65,.18,'sawtooth',.055,-35);emitSparks(player.x,player.z);if(isCop)run.wanted=clamp(run.wanted+.4,0,5);}}
 else if(d<5&&d>3.05&&player.speed>12&&time-other.near>5){other.near=time;run.nearMisses++;run.style+=50;pop('CLOSE CALL +50');sound(730,.08,'triangle',.03,130);}
}
function updatePolice(dt){
 copSpawnTimer-=dt;const wantedCount=run.wanted<.8?0:Math.min(5,Math.ceil(run.wanted)+1);if(cops.length<wantedCount&&copSpawnTimer<=0){spawnCop();copSpawnTimer=3;}
 let seen=false,close=0;
 for(let i=cops.length-1;i>=0;i--){const c=cops[i],d=dist(c.car,player),sees=d<34&&visible(c.car,player);c.timer-=dt;if(sees&&run.wanted>=.8){c.lastSeen={x:player.x,z:player.z};c.lost=0;seen=true;}else c.lost+=dt;
  if(c.lost>10&&run.wanted<.8&&d>23){world.remove(c.view.group);disposeVehicle(c.view);cops.splice(i,1);continue;}
  if(c.timer<=0){const chase=run.wanted>=.8?c.lastSeen:{x:54,z:-54};c.path=route(c.car,chase);c.timer=.7;}
  aiSteer(c,c.path,run.wanted>=.8?17+run.wanted*.6:9,dt);c.red.material.emissiveIntensity=Math.floor(time*7)%2===0?4:.25;c.blue.material.emissiveIntensity=Math.floor(time*7)%2===0?.25:4;vehicleContact(c,true,dt);if(d<5)close++;
 }
 if(run.wanted>=.8){if(seen){run.escape=0;}else{run.escape+=dt;if(run.escape>6){run.wanted=Math.max(0,run.wanted-dt*.55);if(run.wanted<.8){run.wanted=0;run.style+=150;toast('YOU LOST THE COPS. +150 STYLE','good');sound(440,.22,'triangle',.05,440);}}}}
 run.busted=close>0&&player.speed<2.2&&run.wanted>=.8?run.busted+dt:Math.max(0,run.busted-dt*1.7);
 if(run.busted>4.5)finish(false,'BOXED IN.');
 roadblockTimer-=dt;if(run.wanted>=2.8&&roadblockTimer<=0){makeRoadblock();roadblockTimer=32;}
}
function makeRoadblock(){const points=routePoints.filter(p=>dist(player,p)>25&&dist(player,p)<75&&dist(p,HOME)>16);if(!points.length)return;const p=points[Math.min(1,points.length-1)],onVertical=ROAD.some(x=>Math.abs(p.x-x)<.1);for(let i=-1;i<=1;i++){const x=p.x+(onVertical?i*2.7:0),z=p.z+(onVertical?0:i*2.7);if(!blocked(x,z,.8))addBreakable('barrier',x,z,8,onVertical?Math.PI/2:0,true);}run.roadblockCount++;toast('ROADBLOCK AHEAD. FIND A GAP OR HIT IT.','bad');}
function damage(amount){if(damageCooldown>0||mode!=='driving')return;player.health=Math.max(0,player.health-amount);damageCooldown=.6;$('damageFlash').style.opacity=.75;setTimeout(()=>{$('damageFlash').style.opacity=0;},180);}
function emitSparks(x,z){for(let i=0;i<7;i++){const mesh=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,.12),material('#f7da98',{emissive:'#f7ca76',emissiveIntensity:.6}));mesh.position.set(x,.7,z);world.add(mesh);sparks.push({mesh,vx:(Math.random()-.5)*9,vz:(Math.random()-.5)*9,vy:2+Math.random()*4,life:.7});}}
function breakProps(dt){for(const d of destructibles){if(d.broken)continue;const distance=Math.hypot(player.x-d.x,player.z-d.z);if(distance<d.r+1.3&&player.y<1.3){if(player.speed>4){d.broken=true;d.view.visible=false;const mesh=d.view.clone(true);mesh.visible=true;world.add(mesh);debris.push({mesh,vx:player.vx*.55+(Math.random()-.5)*4,vz:player.vz*.55+(Math.random()-.5)*4,vy:4.5,life:2.5});player.vx*=.88;player.vz*=.88;run.style+=d.roadblock?75:15;if(d.roadblock)pop('ROADBLOCK SMASH +75');else if(time-smashTimer>1){pop('SMASH +15');smashTimer=time;}sound(105,.15,'sawtooth',.035,-60);emitSparks(d.x,d.z);}else{const nx=(player.x-d.x)/(distance||1),nz=(player.z-d.z)/(distance||1);player.vx+=nx*dt*5;player.vz+=nz*dt*5;}}}}
function tireTrail(){const geo=new THREE.PlaneGeometry(.15,.9),mat=new THREE.MeshBasicMaterial({color:'#263d44',transparent:true,opacity:.45,depthWrite:false});for(const sign of [-1,1]){const mesh=new THREE.Mesh(geo.clone(),mat.clone());mesh.rotation.set(-Math.PI/2,0,-player.heading);mesh.position.set(player.x+Math.cos(player.heading)*sign*.9-Math.sin(player.heading)*1.5,.15,player.z-Math.sin(player.heading)*sign*.9-Math.cos(player.heading)*1.5);world.add(mesh);trails.push({mesh,life:5});}geo.dispose();mat.dispose();}
let trailTime=0,driftEarn=0;
function effects(dt){
 cityState?.update(time);for(const r of residents){const dest=r.direction>0?r.b:r.a,pos=r.group.position,dx=dest.x-pos.x,dz=dest.z-pos.z,length=Math.hypot(dx,dz);if(length<.16)r.direction*=-1;else{pos.x+=dx/length*dt*.85;pos.z+=dz/length*dt*.85;r.group.rotation.y=Math.atan2(dx,dz);}r.mixer.update(dt);}
 for(const p of pickups){p.marker.diamond.rotation.y+=dt;p.marker.diamond.position.y=3.6+Math.sin(time*2+p.stop.x)*.2;p.actor.mixer.update(dt);}
 for(const d of drops){d.marker.diamond.rotation.y+=dt*1.5;d.marker.mesh.material.opacity=.55+Math.sin(time*3)*.2;}
 garageMarker.diamond.rotation.y+=dt;garageMarker.mesh.material.opacity=.5+Math.sin(time*2)*.15;
 for(let i=debris.length-1;i>=0;i--){const d=debris[i];d.life-=dt;d.vy-=12*dt;d.mesh.position.x+=d.vx*dt;d.mesh.position.z+=d.vz*dt;d.mesh.position.y=Math.max(.1,d.mesh.position.y+d.vy*dt);d.mesh.rotation.x+=dt*2;d.mesh.rotation.z+=dt*3;if(d.life<=0){world.remove(d.mesh);debris.splice(i,1);}}
 for(let i=sparks.length-1;i>=0;i--){const s=sparks[i];s.life-=dt;s.vy-=10*dt;s.mesh.position.x+=s.vx*dt;s.mesh.position.z+=s.vz*dt;s.mesh.position.y+=s.vy*dt;if(s.life<=0){world.remove(s.mesh);s.mesh.geometry.dispose();sparks.splice(i,1);}}
 for(let i=trails.length-1;i>=0;i--){const t=trails[i];t.life-=dt;t.mesh.material.opacity=t.life/5*.45;if(t.life<=0){world.remove(t.mesh);t.mesh.geometry.dispose();t.mesh.material.dispose();trails.splice(i,1);}}
 if(mode==='driving'){trailTime-=dt;if(player.drifting&&player.y<.3){run.drift+=dt;driftEarn+=dt;run.style+=dt*18;if(trailTime<=0){tireTrail();trailTime=.09;}if(driftEarn>1.1){pop('DRIFT +'+Math.floor(driftEarn*18));}}else driftEarn=0;
 if(player.boosting&&trailTime<=0){const mesh=new THREE.Mesh(new THREE.ConeGeometry(.25,1.5,5),material('#9fdfee',{emissive:'#75d6ff',emissiveIntensity:1}));mesh.position.set(player.x-Math.sin(player.heading)*2.3,.5+player.y,player.z-Math.cos(player.heading)*2.3);mesh.rotation.x=Math.PI/2;mesh.rotation.z=-player.heading;world.add(mesh);sparks.push({mesh,vx:-player.vx*.2,vz:-player.vz*.2,vy:0,life:.13});trailTime=.09;}
 }
 if(time>toastUntil)$('toast').classList.add('hidden');if(time>popUntil)$('stylePop').classList.add('hidden');
}
const mapCtx=$('minimap').getContext('2d');
function drawMap(){const c=mapCtx,size=300,extent=LIMIT+4,span=extent*2,m=v=>(v+extent)/span*size;c.fillStyle='#132236';c.fillRect(0,0,size,size);for(const b of BLOCKS){c.fillStyle=b.park?'#356853':b.district==='docks'?'#526379':'#344b66';c.fillRect(m(b.x-b.w/2),m(b.z-b.d/2),b.w/span*size,b.d/span*size);}c.strokeStyle='#233b53';c.lineWidth=8;for(const n of ROAD){c.beginPath();c.moveTo(m(-LIMIT),m(n));c.lineTo(m(LIMIT),m(n));c.stroke();c.beginPath();c.moveTo(m(n),m(-LIMIT));c.lineTo(m(n),m(LIMIT));c.stroke();}c.strokeStyle=bankRoute?'#e7d38a':'#a9e5d5';c.lineWidth=2;c.beginPath();routePoints.forEach((p,i)=>i?c.lineTo(m(p.x),m(p.z)):c.moveTo(m(p.x),m(p.z)));c.stroke();for(const p of pickups)if(!p.job.picked&&p.job.cooldown<=0){c.fillStyle=['','#acdba9','#e7ce8b','#e7a084'][p.stop.type];c.beginPath();c.arc(m(p.stop.x),m(p.stop.z),3,0,Math.PI*2);c.fill();}for(const p of run.passengers){c.fillStyle='#8cdee3';c.fillRect(m(p.dest.x)-3,m(p.dest.z)-3,6,6);}c.fillStyle='#dff5ad';c.fillRect(m(HOME.x)-4,m(HOME.z)-4,8,8);for(const cop of cops){c.fillStyle='#f39376';c.beginPath();c.arc(m(cop.car.x),m(cop.car.z),3,0,Math.PI*2);c.fill();}c.save();c.translate(m(player.x),m(player.z));c.rotate(-player.heading);c.fillStyle='#fff0b7';c.strokeStyle='#173d40';c.lineWidth=1;c.beginPath();c.moveTo(0,6);c.lineTo(-4,-5);c.lineTo(4,-5);c.closePath();c.fill();c.stroke();c.restore();}
let passengerHTML='';
function updateHUD(){
 const seconds=Math.max(0,Math.ceil(run.time));$('timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('timerBox').classList.toggle('urgent',seconds<30);$('haul').textContent=Math.floor(run.haul+run.style).toLocaleString();$('combo').textContent='×'+run.combo.toFixed(2)+' DELIVERY STREAK';$('speed').textContent=Math.round(player.speed*4.6);const hp=clamp(player.health/player.config.health*100,0,100);$('health').textContent=Math.ceil(hp)+'%';$('healthFill').style.width=hp+'%';$('healthFill').style.background=hp<30?'#f3a180':'#a0dec0';$('nitroFill').style.width=player.nitro+'%';$('nitroText').textContent=player.boosting?'BOOSTING':player.nitro>98?'READY':Math.floor(player.nitro)+'%';
 const stars=run.wanted<.8?0:Math.ceil(run.wanted);$('stars').innerHTML=Array.from({length:5},(_,i)=>`<span class="${i<stars?'lit':''}">★</span>`).join('');$('wantedLabel').textContent=stars?run.escape>1?'SEARCHING · STAY OUT OF SIGHT':'PURSUIT · SHAKE THEM OFF':'KEEP IT CLEAN';$('escapeFill').style.width=stars?clamp(run.escape/6*100,0,100)+'%':'0';$('bustMeter').classList.toggle('hidden',run.busted<.4);$('bustFill').style.width=clamp(run.busted/4.5*100,0,100)+'%';
 if(target){$('dispatchLabel').textContent=target.kind==='garage'?'CASH OUT / GARAGE':target.kind==='drop'?'ON BOARD / DROP-OFF':'DISPATCH / PICKUP';$('dispatchName').textContent=target.name;const distance=Math.round(dist(player,target.point));$('dispatchDetail').innerHTML=target.kind==='pickup'?`${target.pickup.job.name} · <span class="fare">${Math.round(target.pickup.job.value*run.combo).toLocaleString()} CR</span><br>${distance} m · Stop in the ring.`:target.kind==='drop'?`${distance} m · Stop in the blue ring.<br><span class="fare">${Math.round(target.fare.value*run.combo).toLocaleString()} CR</span> + 40 seconds.`:`${distance} m · Stop in the garage ring.<br>Bank your haul to keep it.`;}
 $('routeBtn').textContent=bankRoute?'↗ ROUTE TO JOBS':'⌂ ROUTE TO GARAGE';
 const html=`<div class="seat-count">PASSENGERS ${run.passengers.length} / ${player.config.seats}</div>`+(run.passengers.length?run.passengers.map(p=>`<div class="passenger"><div>${p.dest.name}<br><span class="fare">${Math.round(p.value*run.combo).toLocaleString()} CR</span></div><button data-dest="${p.id}" aria-label="Route to ${p.dest.name}">ROUTE</button></div>`).join(''):'<div class="empty-seats">Empty seats. Find your next fare.</div>');
 if(html!==passengerHTML){passengerHTML=html;$('passengers').innerHTML=html;$('passengers').querySelectorAll('[data-dest]').forEach(b=>b.onclick=()=>{targetLock=b.dataset.dest;pickupLock=null;bankRoute=false;refreshRoute();updateHUD();});}drawMap();
}
function cameraUpdate(dt){const portrait=innerWidth<600;
 if(mode==='menu'){
  const orbit=Math.sin(time*.11)*.6,desired=new THREE.Vector3(HOME.x-8.5+orbit,6.5,HOME.z+10.5);
  cameraPosition.lerp(desired,1-Math.exp(-dt*3));camera.position.copy(cameraPosition);camera.lookAt(HOME.x,1.05,HOME.z);camera.fov=THREE.MathUtils.damp(camera.fov,portrait?40:35,5,dt);
  camera.setViewOffset(innerWidth,innerHeight,portrait?0:-innerWidth*.215,portrait?innerHeight*.22:0,innerWidth,innerHeight);camera.updateProjectionMatrix();
 }else{
  camera.clearViewOffset();const difference=Math.atan2(Math.sin(player.heading-cameraHeading),Math.cos(player.heading-cameraHeading));cameraHeading+=difference*(1-Math.exp(-dt*(player.drifting?2.4:4.8)));
  cameraTarget.lerp(new THREE.Vector3(player.x,0,player.z),1-Math.exp(-dt*13));const high=profile.camera==='high',speedPull=clamp(player.speed/30,0,1)*2;
  const distance=high?13:portrait?18+speedPull:16+speedPull,height=high?35:portrait?18:12.5;
  const desired=new THREE.Vector3(cameraTarget.x-Math.sin(cameraHeading)*distance,height+player.y*.45,cameraTarget.z-Math.cos(cameraHeading)*distance);
  cameraPosition.lerp(desired,1-Math.exp(-dt*9));camera.position.copy(cameraPosition);
  camera.lookAt(cameraTarget.x+Math.sin(cameraHeading)*4.5,player.y*.45+.5,cameraTarget.z+Math.cos(cameraHeading)*4.5);
  camera.fov=THREE.MathUtils.damp(camera.fov,50+(player.boosting?6:0),4,dt);camera.updateProjectionMatrix();
 }}
camera.position.copy(cameraPosition);camera.lookAt(HOME.x-4,0,HOME.z-6);
function tick(){requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.04);if(!paused)time+=dt;
 if(ready&&!paused){
  if(mode==='driving'){run.time=Math.max(0,run.time-dt);run.elapsed+=dt;damageCooldown-=dt;currentInput={throttle:(keys.KeyW||keys.ArrowUp||mobile.gas?1:0)-(keys.KeyS||keys.ArrowDown||mobile.reverse?1:0),steer:(keys.KeyD||keys.ArrowRight||mobile.right?1:0)-(keys.KeyA||keys.ArrowLeft||mobile.left?1:0),brake:!!(keys.Space||mobile.drift),boost:!!(keys.ShiftLeft||keys.ShiftRight||mobile.boost)};drive(player,currentInput,dt);if(player.impact>3&&damageCooldown<=0){damage(Math.min(20,player.impact*.8));run.crashes++;emitSparks(player.x,player.z);sound(72,.18,'sawtooth',.045,-32);}if(player.landed){run.airJumps++;run.style+=125;pop('AIR TIME +125');sound(240,.14,'triangle',.04,310);}animateCar(playerView,player,dt,currentInput.steer);breakProps(dt);stopActivities(dt);if(mode==='driving'){updatePolice(dt);updateTraffic(dt);if(player.health<=0)finish(false,'RIDE TOTALED.');else if(run.time<=0)finish(false,'SHIFT OVER.');}routeTimer-=dt;if(routeTimer<=0){refreshRoute();routeTimer=.8;}if(time-lastHUD>.1){updateHUD();lastHUD=time;}}
  else if(mode==='menu'){animateCar(playerView,player,dt);updateTraffic(dt);for(const p of pickups)p.actor.mixer.update(dt);}
  effects(dt);cameraUpdate(dt);
 }
 if(ready)fadeObstructions(dt);updateAudio();renderer.render(scene,camera);
}
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});refreshMenu();tick();

const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
register({name:'read_getaway_state',title:'Read Getaway game',description:'Read the current solo driving run, car, passengers, route, wanted level, and arcade credits.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters accepted.');return{mode,ready,paused,car:profile.selected,credits:profile.credits,haul:Math.floor(run.haul+run.style),passengers:run.passengers.length,wanted:run.wanted,secondsLeft:Math.ceil(run.time),target:target?.name,livePayouts:false};}});
register({name:'start_getaway_shift',title:'Start a driving shift',description:'Start a fresh solo arcade driving run, replacing the current unbanked run. Uses the same Start your shift action.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters accepted.');if(!ready)throw new Error('The city is still loading.');startRun();return{mode,car:profile.selected,secondsLeft:150};}});
addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
